export const viewerCss: string = ":root {\n    font-family: system-ui, sans-serif;\n    color: #24272c;\n    background: #eceef1;\n}\nbody {\n    margin: 0;\n}\nbutton,\nsummary {\n    font: inherit;\n    cursor: pointer;\n}\nbutton {\n    color: inherit;\n    border: 1px solid #c6cad0;\n    border-radius: 0.3rem;\n    background: white;\n    padding: 0.5rem 0.8rem;\n}\nbutton:hover,\nsummary:hover {\n    background: #e5edf8;\n}\nbutton:disabled {\n    opacity: 0.45;\n    cursor: default;\n}\n:focus-visible {\n    outline: 3px solid #2463b5;\n    outline-offset: 3px;\n}\n[hidden] {\n    display: none !important;\n}\n.presenit-layout {\n    display: flex;\n    height: calc(100dvh - 64px);\n    min-height: 160px;\n}\n#presenit-stage {\n    flex: 1;\n    min-width: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n}\n.presenit-ready #presenit-stage .presenit-deck {\n    width: var(--presenit-scaled-width);\n    height: var(--presenit-scaled-height);\n    position: relative;\n    background: transparent;\n}\n.presenit-ready #presenit-stage .presenit-slide {\n    position: absolute;\n    left: 0;\n    top: 0;\n    transform: scale(var(--presenit-scale));\n    transform-origin: top left;\n}\n.presenit-ready #presenit-stage .presenit-slide:not(.is-current) {\n    display: none;\n}\n.presenit-toolbar {\n    position: fixed;\n    bottom: 0;\n    inset-inline: 0;\n    height: 64px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 0.6rem;\n    background: #fff;\n    border-top: 1px solid #c6cad0;\n    box-sizing: border-box;\n    z-index: 20;\n}\n.presenit-counter {\n    min-width: 8.5rem;\n    text-align: center;\n    font-variant-numeric: tabular-nums;\n    font-size: 0.9rem;\n}\n.presenit-menu {\n    position: relative;\n}\n.presenit-menu summary {\n    padding: 0.5rem 0.6rem;\n}\n.presenit-menu-actions {\n    position: absolute;\n    bottom: 3rem;\n    right: 0;\n    width: max-content;\n    display: grid;\n    gap: 0.3rem;\n    background: white;\n    padding: 0.6rem;\n    border: 1px solid #c6cad0;\n    border-radius: 0.4rem;\n    box-shadow: 0 0.5rem 2rem #0002;\n}\n.presenit-menu-actions button {\n    text-align: left;\n}\nbutton[aria-pressed=\"true\"] {\n    background: #dceafd;\n    border-color: #2463b5;\n}\n.presenit-presenter {\n    width: 26%;\n    min-width: 260px;\n    overflow: auto;\n    padding: 1.25rem;\n    box-sizing: border-box;\n    background: white;\n}\n.presenit-ui-title {\n    font-size: 1rem;\n    margin: 0 0 0.5rem;\n    font-weight: 600;\n}\n.presenit-timer {\n    display: block;\n    font-size: 2.5rem;\n    font-variant-numeric: tabular-nums;\n}\n.presenit-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.4rem;\n}\n.presenit-presenter h2 {\n    font-size: 0.9rem;\n    margin-top: 1.5rem;\n}\n.presenit-preview {\n    width: 100%;\n    aspect-ratio: 16/9;\n    overflow: hidden;\n    background: #eceef1;\n}\n.presenit-preview > .presenit-slide,\n.presenit-thumb > .presenit-slide {\n    transform: scale(var(--presenit-scale));\n    transform-origin: top left;\n    pointer-events: none;\n}\n.presenit-notes {\n    white-space: pre-wrap;\n    line-height: 1.65;\n}\n.presenit-overview {\n    border: 0;\n    border-radius: 0.5rem;\n    width: min(1100px, 90vw);\n    max-height: 85dvh;\n    padding: 1.2rem;\n    color: #24272c;\n    background: #f8f9fb;\n}\n.presenit-overview::backdrop {\n    background: #141923b3;\n}\n.presenit-overview header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n}\n.presenit-overview h2 {\n    font-size: 1.2rem;\n}\n.presenit-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));\n    gap: 1rem;\n}\n.presenit-grid > button {\n    text-align: left;\n    padding: 0.5rem;\n    overflow: hidden;\n}\n.presenit-thumb {\n    width: 100%;\n    aspect-ratio: 16/9;\n    overflow: hidden;\n    margin-bottom: 0.5rem;\n}\n.presenit-thumb .is-concealed {\n    visibility: visible;\n    opacity: 1;\n}\n.presenit-blackout {\n    position: fixed;\n    inset: 0;\n    background: black;\n    z-index: 15;\n}\n.presenit-laser {\n    position: fixed;\n    width: 12px;\n    height: 12px;\n    background: #e72e39;\n    border: 2px solid white;\n    border-radius: 50%;\n    box-shadow: 0 0 8px #e72e39;\n    translate: -50% -50%;\n    z-index: 30;\n    pointer-events: none;\n}\n.presenit-status {\n    position: fixed;\n    left: 1rem;\n    bottom: 65px;\n    font-size: 0.85rem;\n    background: white;\n    max-width: 32rem;\n    z-index: 21;\n}\n.presenit-status:empty {\n    display: none;\n}\n.presenit-slide [data-presenit-at] {\n    transition: opacity var(--presenit-fragment-duration, 0.3s) ease;\n}\n.presenit-slide .is-concealed {\n    visibility: hidden;\n    opacity: 0;\n}\n@media (prefers-reduced-motion: reduce) {\n    .presenit-slide [data-presenit-at] {\n        transition: none;\n    }\n}\n@media (max-width: 700px) {\n    .is-presenter .presenit-layout {\n        flex-direction: column;\n        overflow: auto;\n    }\n    .is-presenter #presenit-stage {\n        min-height: 42dvh;\n    }\n    .presenit-presenter {\n        width: 100%;\n        min-width: 0;\n        overflow: visible;\n    }\n    .presenit-toolbar {\n        gap: 0.2rem;\n    }\n    button {\n        padding: 0.5rem;\n    }\n}\n@media print {\n    html,\n    body {\n        background: white !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .presenit-layout,\n    #presenit-stage {\n        display: block !important;\n        height: auto !important;\n        overflow: visible !important;\n    }\n    .presenit-ready #presenit-stage .presenit-deck {\n        width: auto;\n        height: auto;\n    }\n    .presenit-ready #presenit-stage .presenit-slide {\n        display: flex !important;\n        position: relative !important;\n        transform: none !important;\n        translate: none !important;\n        opacity: 1 !important;\n        margin: 0 !important;\n        border: 0 !important;\n        break-after: page;\n        break-inside: avoid;\n        print-color-adjust: exact;\n        -webkit-print-color-adjust: exact;\n    }\n    #presenit-stage .presenit-slide:last-child {\n        break-after: auto;\n    }\n    .presenit-slide .is-concealed {\n        visibility: visible !important;\n        opacity: 1 !important;\n    }\n    .presenit-toolbar,\n    .presenit-presenter,\n    .presenit-overview,\n    .presenit-status,\n    .presenit-laser,\n    .presenit-blackout,\n    noscript {\n        display: none !important;\n    }\n    .katex .katex-mathml {\n        display: none;\n    }\n}\n";
